// Generated by `factory render`. Do not edit.
// The one decision for a static-analysis finding: introduced by the change or already on the base, and for a secret,
// whether the matched value itself is already on the base. Every place that judges findings runs this file: the local
// slots (runner.mjs, the commit gate) and the generated CI script (.factory/bin/analysis/ci.mjs, which gets a copy of
// this file and of baseline.mjs), so a tree gets the same verdict on the machine and in CI. It uses only Node's own
// modules, git and baseline.mjs.
//
// A secret value is read here, in this process, from the line the scanner pointed at, and never written to a report, a
// log, an argument list or an agent: lookups go through a private temporary pattern file that is removed at once.
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { classify } from './baseline.mjs';

const gitRun = (cwd, args) => spawnSync('git', args, { cwd, encoding: 'utf8', maxBuffer: 256 * 1024 * 1024, timeout: 300_000 });
const COMMIT = /^[0-9a-f]{40}$/;
const listOf = (r) => (r.status === 0 ? String(r.stdout).split('\n').filter(Boolean) : []);

// The files a change touches and, per file, the line numbers it added or changed (null: a file the merge-base does not
// have, counted whole). Measured from the merge-base, never from the base's tip (a base that moved on would otherwise
// count its own new lines as this change's). `worktree`: the working tree with its uncommitted and untracked files (a
// local scan); otherwise HEAD (CI, and a local scan of a clean tree, which is the same).
export function changedMap(cwd, mergeBase, { worktree = false } = {}) {
  const to = worktree ? [] : ['HEAD'];
  const files = new Set(listOf(gitRun(cwd, ['diff', '--name-only', '--diff-filter=ACMR', mergeBase, ...to])));
  if (worktree) for (const f of listOf(gitRun(cwd, ['ls-files', '--others', '--exclude-standard']))) files.add(f);
  const map = new Map();
  for (const f of files) {
    if (gitRun(cwd, ['cat-file', '-e', `${mergeBase}:${f}`]).status !== 0) {
      map.set(f, null);
      continue;
    }
    const lines = new Set();
    for (const m of String(gitRun(cwd, ['diff', '-U0', '--no-ext-diff', mergeBase, ...to, '--', f]).stdout).matchAll(/^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/gm)) for (let i = 0; i < (m[2] === undefined ? 1 : Number(m[2])); i++) lines.add(Number(m[1]) + i);
    map.set(f, lines);
  }
  return map;
}

function entropy(s) {
  const counts = new Map();
  for (const c of s) counts.set(c, (counts.get(c) ?? 0) + 1);
  let h = 0;
  for (const n of counts.values()) h -= (n / s.length) * Math.log2(n / s.length);
  return h;
}

const spanOf = (text, { column = null, endColumn = null } = {}) => {
  const line = String(text ?? '');
  return Number.isInteger(column) && column > 0 ? line.slice(column - 1, Number.isInteger(endColumn) && endColumn >= column ? endColumn : undefined) : null;
};

// The tokens on a line that can be a secret value: 12 or more key-like characters with letters and digits and enough
// entropy, inside the scanner's column span when it gave one. Longest first.
export function valueCandidates(text, { column = null, endColumn = null } = {}) {
  const span = spanOf(text, { column, endColumn }) ?? String(text ?? '');
  const tokens = span.match(/[A-Za-z0-9+/_\-=]{12,}/g) ?? [];
  const out = [...new Set(tokens.map((t) => t.replace(/=+$/, '')))].filter((t) => t.length >= 12 && /[0-9]/.test(t) && /[A-Za-z]/.test(t) && entropy(t) >= 3);
  return out.sort((a, b) => b.length - a.length);
}

// The matched secret itself: a scanner's match ends with the value (`key = value`, the closing quote at most), so it
// is the last value-like run of the span, whatever its entropy. Null without a span or when that run is too short to
// stand for a value (then nothing about the value can be proven).
export function matchedSecret(text, { column = null, endColumn = null } = {}) {
  const span = spanOf(text, { column, endColumn });
  if (span == null) return null;
  const runs = span.match(/[A-Za-z0-9+/_\-=.~]+/g) ?? [];
  const last = (runs.at(-1) ?? '').replace(/\.+$/, '');
  return last.length >= 8 ? last : null;
}

// The text of a finding's line: from the commit the scanner found it in (a history finding), else from the working tree.
export function findingLine(cwd, f) {
  if (!f?.file || !Number.isInteger(f.line) || f.line < 1) return null;
  let text = null;
  if (COMMIT.test(String(f.vendorFingerprint ?? ''))) {
    const r = gitRun(cwd, ['show', `${f.vendorFingerprint}:${f.file}`]);
    if (r.status === 0) text = r.stdout;
  }
  if (text == null) {
    try {
      text = fs.readFileSync(path.join(cwd, f.file), 'utf8');
    } catch {
      return null;
    }
  }
  return text.split('\n')[f.line - 1] ?? null;
}

// git grep with fixed-string patterns read from a private temporary file (never the command line).
function grepValues(cwd, values, args) {
  if (!values.length) return [];
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'factory-values-'));
  const file = path.join(dir, 'patterns');
  try {
    fs.writeFileSync(file, `${values.join('\n')}\n`, { mode: 0o600 });
    return listOf(gitRun(cwd, ['grep', '-l', '-I', '-F', '-f', file, ...args]));
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

// The files of a commit that hold any of the values ([] when none does).
export function whereOnRev(cwd, rev, values) {
  if (!rev) return [];
  return grepValues(cwd, values, [rev, '--']).map((l) => l.slice(rev.length + 1));
}

// The files of the working tree (tracked and untracked, not ignored) that hold any of the values.
export function whereInWorktree(cwd, values) {
  return grepValues(cwd, values, ['--untracked', '--']);
}

// Where the merge-base already holds the finding's matched secret itself: the files, or [] when it does not or when
// that cannot be proven. With a span, the matched secret (the span's last value run: a scanner's match is `key = value`)
// decides alone; the text before it is the key side, whatever it holds (held-out C20, HINT-1: the keyword came from a
// fake value and the matched secret was a user id on main). Without a span, every candidate on the line must be on the
// base.
export function valueOnBase(cwd, f, mergeBase) {
  if (!mergeBase) return [];
  const text = findingLine(cwd, f);
  const at = { column: f.column ?? null, endColumn: f.endColumn ?? null };
  const secret = matchedSecret(text, at);
  const values = secret ? [secret] : valueCandidates(text, at);
  if (!values.length) return [];
  const files = new Set();
  for (const v of values) {
    const where = whereOnRev(cwd, mergeBase, [v]);
    if (!where.length) return [];
    for (const w of where) files.add(w);
  }
  return [...files];
}

// Splits a secret tool's introduced findings: the matched value already on the base at the merge-base is pre-existing,
// with a note naming where it lives; every other one stays introduced (a new secret blocks).
export function settleSecretFindings(cwd, findings, { mergeBase }) {
  const introduced = [];
  const preexisting = [];
  for (const f of findings) {
    const files = valueOnBase(cwd, f, mergeBase);
    if (!files.length) {
      introduced.push(f);
      continue;
    }
    const where = `${files.slice(0, 3).join(', ')}${files.length > 3 ? ', ...' : ''}`;
    preexisting.push({ ...f, alreadyOnBase: files.slice(0, 10), note: `the same value is already on the base branch (merge-base ${String(mergeBase).slice(0, 7)}) in ${where}: a copy of an existing value, not a new secret of this change` });
  }
  return { introduced, preexisting };
}

// The verdict for one tool's findings on a tree: introduced (charged to the change) or pre-existing. `tool`: its scope,
// baseline and whether its findings are secret values (`secretValues`). `changed`: changedMap(). `base`: the
// merge-base's findings of the tool (merge-base baseline). The same call in every local slot and in CI.
export function decide(tool, findings, { cwd, changed, base = [], mergeBase }) {
  const { introduced, preexisting } = classify(findings, { scope: tool.scope ?? 'repo', baseline: tool.baseline, changed, base });
  if (!tool.secretValues || !introduced.length) return { introduced, preexisting };
  const settled = settleSecretFindings(cwd, introduced, { mergeBase });
  return { introduced: settled.introduced, preexisting: [...preexisting, ...settled.preexisting] };
}
